const e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Automatiseer je printer met veilige ALS-DAN-regels. Standaard uit; activeer elke regel zelf."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Nog geen regels. Voeg er hieronder een toe en activeer die als je er klaar voor bent."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"Regel-engine staat AAN"}},off:{t:0,b:{t:2,i:[{t:3}],s:"Regel-engine staat UIT"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"Inschakelen"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"Uitschakelen"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"Er gebeurt niets totdat zowel de engine als de afzonderlijke regel aan staan."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"Wanneer een print klaar is"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"Wanneer de printer een fout geeft"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"Wanneer een verwarmer stijgt boven"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"Wanneer een verwarmer daalt onder"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"Een melding loggen"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"Een g-code-commando uitvoeren"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"Geactiveerd"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"Gedeactiveerd"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"Bewerken"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Verwijderen"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"Regel verwijderen"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"Regelnaam"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"bijv. Verwarmers uit na print"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"Als (trigger)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Dan (actie)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"Verwarmer"}},value:{t:0,b:{t:2,i:[{t:3}],s:"Temperatuur (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"Bericht"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Wordt getoond in het regellogboek"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"bijv. TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Regel opslaan"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annuleren"}},add:{t:0,b:{t:2,i:[{t:3}],s:"Een regel toevoegen"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"Recente activiteit"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"gemeld"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"g-code uitgevoerd"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"overgeslagen (printer bezig)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"fout"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Gids"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Gids voor de regel-engine"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Sluiten"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wat is de regel-engine?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Hij houdt de printer in de gaten en voert een actie uit wanneer aan een door jou ingestelde voorwaarde wordt voldaan - bijvoorbeeld een notitie loggen wanneer een print klaar is, of de verwarmers uitzetten. Elke regel is ALS (een trigger) DAN (een actie)."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Hoe het veilig blijft"}},body:{t:0,b:{t:2,i:[{t:3}],s:"De engine staat standaard uit en elke regel moet afzonderlijk worden geactiveerd, zodat er niets onverwacht gebeurt. Een regel wordt één keer geactiveerd wanneer de voorwaarde voor het eerst waar wordt. G-code-acties worden alleen uitgevoerd terwijl de printer inactief is - ze worden geweigerd tijdens een print - en elke uitkomst wordt gelogd."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Begrippenlijst"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"Trigger"}},def:{t:0,b:{t:2,i:[{t:3}],s:"De voorwaarde die een regel start, bijv. een print die klaar is of een verwarmer die een temperatuur passeert."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"Actie"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Wat de regel doet wanneer hij wordt geactiveerd: een melding loggen, of een g-code-commando uitvoeren (alleen tijdens inactiviteit)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"Geactiveerd"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Een regel die ingeschakeld is. Gedeactiveerde regels blijven bewaard maar worden nooit uitgevoerd."}}}}}}};export{e as default};
